-- PAPER-LEARN-PROBATION-SETTLE-1 part 8 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 5538 to 6022 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_08 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_08 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_08 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_08)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_08 AS SELECT * FROM paper_learnings WHERE id IN (5538, 5539, 5540, 5601, 5602, 5608, 5609, 5759, 5760, 5761, 5762, 5763, 5764, 5788, 5790, 5791, 5792, 5794, 5795, 5860, 5861, 5865, 6015, 6016, 6022);

UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; provenance): Concealment is not possible by design: pipeline papers carry the provenance section, pull requests and commits state AI authorship, and reopen rates and corrections are tracked (issue_lifecycle, the errata pipeline).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5538 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): A paper''s self-disclosed limitation is already read by the pipeline reviewer and CLAIM-INTEGRITY-1; auto-filing an issue per self-declared unvalidated claim would add a producer with no doer and no measured miss, against OWNER-NO-LOOSE-ENDS-1. Re-propose with a limitation statement that went unactioned and mattered.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5539 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; blocker): Unknown is verified before it is asserted: SESSION-EFFECTIVENESS-1 requires a read before a claim, and a claim of blocked, owner only or cannot must be attempted and recorded in blocker_redteam (v_blocker_claims, unverified_blocker_claims) before it stands.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5540 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): The misuse named is quoting a headline saving without its assumptions. Fleet figures come from read tool output with their window and formula (metric rows state both, pull requests name the metric, direction and size), and no fleet artifact is shown with a number stripped of its conditions. Re-propose with such an artifact.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5601 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; belief): Falsifiers are recorded beside adopted rules: belief_registry holds each belief the fleet acts on with a belief-<key> probe that reads false when the belief fails, and a prediction states what result would count as a miss.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5602 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): A single composite quality score is not the fleet''s measure: v_output_quality_by_surface reads several outcome measures per surface from output_quality_measures, proxies are labelled and never targets, and a pool mean is explicitly not accepted as evidence (OUTPUT-QUALITY-LEDGER-1).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5608 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): Pareto improvement is the stated merge test for metrics: a gain in a target metric while a guard metric worsens is a regression (INTEGRITY-GUARDS-1), and a change is kept only if the target moved and no guard worsened (PROACTIVE-PROGRAMS-1 item 4).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5609 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Asymmetric falsification of a worst-case envelope is the paper''s statistical argument about its psychophysical bound; fleet triggers are breach thresholds on measured metrics, not analytical envelopes, and a recovery is read through the probe''s two-pass and relapse rules.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5759 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Per-event samples are already kept where a max-error trigger would need them: remediation_verifications, fleet_runs, decision_log and issue_lifecycle are append-only per-event ledgers, so a maximum is a SQL expression over them. Re-propose with a trigger that could not be written for lack of per-event data.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5760 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; paperledger): A correction that rewrites more than was flagged is visible and reversible: every change to a paper is an immutable row in paper_change_ledger with the full prior body in paper_change_bodies (PAPER-LEDGER-1), and CLAUDE.md allows one change per component.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5761 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): No pipeline paper or doctrine amendment is shown with a number that lost its enabling assumptions; CITE-FULLTEXT-1 grounds citations on full texts and CLAIM-INTEGRITY-1 holds unsupported claims. Re-propose with an instance that propagated an unconditioned number.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5762 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; birth): A numeric refutation condition is fixed when an issue is filed: the closing probe is written at birth (519 open issues, 0 without a contract) and METRIC-TRIGGER tickets get their trigger''s probe from contract_probe_templates_v1.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5763 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; budgetnote): Constants are recorded with how they were set: a cap changes only by a fleet_budget migration with its note, a guard or probe change by a migration with its rollback line and the measurement that justified it (RULE-8-RETIRED-1), and a trigger threshold sits in analytics_metric_triggers with its notes.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5764 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; verifylayers): A probe must measure the defect it closes on: CLAUDE.md forbids a probe that already passes while the defect exists, VACUOUS-PROBE placeholders block closing, and DEPLOY-PROBES-1 requires a live run of any new probe before it can revert anything.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5788 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Cross-checking metrics on one artifact for contradictions is the paper''s reading of its own ultrametric counts; the fleet''s reconciliation checks run across stores (v_issue_accounting, fleet graph findings), and no fleet artifact is shown to carry two contradicting metrics.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5790 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; paper-convention): A provenance bundle that carries raw adjacency data is that paper corpus''s own convention; pipeline code runs are recorded in research_run_ledger and research_code_libraries and a paper states its provenance. Re-propose with a pipeline paper whose code result could not be reproduced for lack of inputs.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5791 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; independent): Same-source agreement does not widen scope: trust is computed from verified outcomes read by loops other than the producer, probes run in qnfo-fleet-control and the consumer, and a review reads a risky diff with two disjoint families.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5792 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Loops already emit their sampled scope per run (a triage tick reports examined, kept and settled counts) and carry per-run caps; a rule for partial-population audits has no measured instance of a partial result presented as complete. Re-propose with one.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5794 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; belief,pred): A register of pre-registered checks exists: belief_registry with a belief-<key> probe, decision_log predicted_outcome and outcome_matched, and a closing probe at birth for each issue.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5795 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The p-adic valuation of Jones polynomial coefficients is the paper''s mathematics; no fleet quantity has such a structure to monitor. Re-propose with a fleet quantity that has a p-adic form.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5860 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Membership of a Markov trace in a cyclotomic p-adic ring is a mathematical statement about a knot invariant; no loop has a Temperley-Lieb state to validate. Re-propose with a loop that has such an algebraic state.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5861 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The p-adic skein relation constrains knot-invariant computations; ensemble predictions in the fleet (model verdicts on text and code) have no skein-related input variants. Re-propose with an ensemble whose domain has a stated invariant.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5865 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; verifystage): Tabulated and quoted numbers in pipeline papers are recomputed: qnfo-research-exec''s verify stage extracts numeric claims and recomputes them with a second model family (VERIFY-ZERO-CLAIMS-1 logs the case where none was extracted), and metric tables in the fleet are SQL views over their rows.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 6015 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; paperledger): Narrow corrections are auditable: every change to a paper is an immutable paper_change_ledger row with the full prior body (PAPER-LEDGER-1), so an erratum that rewrote more than was flagged is visible and reversible, and doctrine changes land as single-purpose pull requests (one change per component).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 6016 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; triage): Maturity is recorded and gates adoption: every learning is typed by kind (derived, cited, empirical, assumption), verification and confidence, and passes PAPER-LEARN-TRIAGE-1 against the live mechanisms before it informs a rule; trust widens only from verified outcomes.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 6022 AND fleet_status = 'probation';
